(() => {
  const tryFill = (hints, value) => {
    const inputs = Array.from(document.querySelectorAll('input, textarea, [contenteditable="true"]'));
    for (const el of inputs) {
      const meta = [
        el.getAttribute('name') || '',
        el.getAttribute('placeholder') || '',
        el.getAttribute('aria-label') || '',
        el.id || '',
      ].join(' ').toLowerCase();
      if (!hints.some((h) => meta.includes(h))) continue;
      if (el.isContentEditable) { el.textContent = value; }
      else {
        el.focus();
        el.value = value;
        el.dispatchEvent(new Event('input', { bubbles: true }));
        el.dispatchEvent(new Event('change', { bubbles: true }));
      }
      return 'filled:' + meta.slice(0, 40);
    }
    return 'no-field';
  };
  const a = tryFill(['bestemming', 'destination', 'waarheen', 'zoek', 'search', 'stad'], 'Spanje');
  const b = tryFill(['vertrek', 'depart', 'date', 'datum'], '2026-10-01');
  return a + '|' + b;
})()

